.myPricing{
    --text: '35% DE DESCONTO';
    --first-color: #E5E6D1; /* Fundo da faixa */
    --second-color: #9E9684; /* Cantos da faixa */

    position: relative;
}

.myPricing .myRibbon{
    position: absolute;
    top: -10px;
    left: -10px;
    width: 150px;
    height: 150px;
    display: flex;
    justify-content: center;
    align-items: center;
    overflow: hidden;
}

.myPricing .myRibbon::before{
    content: var(--text);
    position: absolute;
    width: 150%;
    height: 40px;
    background: var(--first-color);
    transform: rotate(-45deg) translateY(-20px);
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 14px;
    font-weight: 600;
    color: #000;
    letter-spacing: 0; /* largura normal */
    box-shadow: 0 5px 10px rgba(0,0,0,0.1);
    font-family: 'Inter', sans-serif;
}

.myPricing .myRibbon::after{
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 10px;
    height: 10px;
    background: var(--second-color);
    z-index: -1;
    box-shadow: 140px -140px var(--second-color);
}

